/* ── Footer ── */
footer{text-align:center;padding:2rem 0;color:var(--text-dim);font-size:.82rem;opacity:.6}

/* ── Animations ── */
.fade-in{opacity:0;transform:translateY(30px);transition:opacity .7s ease,transform .7s ease}
